; masks.asm -- chapter 22: R#3 and R#4 as masks
; generated by gen22.py
        INCLUDE "msx.inc"
        OUTPUT "masks.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
; Three thirds, each of its own 256 shapes and 2,048 colours: every shape of
; third t is the digit t, and its ink colour [1, 4, 3][t]. Then every
; 8 frames new values of R#3 and R#4, and at the end M1 and M2 with M3.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the picture is drawn
        VDP_REG 0, $02          ; Graphic II: 256 x 192 pixels (chapter 22)
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $FF          ; colours            $2000, 6,144 bytes
        VDP_REG 4, $03          ; patterns           $0000, 6,144 bytes
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; patterns: every pixel paper
        ld bc, 6144
g2p:    xor a
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2p
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld bc, 6144
g2c:    ld a, $1F
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2c
        VRAM_WRITE $1800        ; names: 0 to 255 in each third
        ld b, 3
g2n:    xor a
g2n1:   out (VDP_DATA), a
        inc a
        jr nz, g2n1
        djnz g2n
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld de, $0000
        ld a, '0'
        call digit              ; all 256 shapes of third 0: the digit 0
        VRAM_WRITE $2000        ; and all its colours: ink 1 on white
        ld bc, 2048
c0:     ld a, $1F
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, c0
        ld de, $0800
        ld a, '1'
        call digit              ; all 256 shapes of third 1: the digit 1
        VRAM_WRITE $2800        ; and all its colours: ink 4 on white
        ld bc, 2048
c1:     ld a, $4F
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, c1
        ld de, $1000
        ld a, '2'
        call digit              ; all 256 shapes of third 2: the digit 2
        VRAM_WRITE $3000        ; and all its colours: ink 3 on white
        ld bc, 2048
c2:     ld a, $3F
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, c2
        VDP_REG 7, $1F          ; ink black for M1, backdrop white
        ld b, 8
        call frames
s0:     VDP_REG 0, $02          ; Graphic II, every mask bit set
        VDP_REG 3, $FF
        VDP_REG 4, $03
        VDP_REG 1, $C0
t0:
        ld b, 8
        call frames
s1:     VDP_REG 0, $02          ; R#4 = $00: one set of shapes
        VDP_REG 3, $FF
        VDP_REG 4, $00
        VDP_REG 1, $C0
t1:
        ld b, 8
        call frames
s2:     VDP_REG 0, $02          ; R#4 = $01
        VDP_REG 3, $FF
        VDP_REG 4, $01
        VDP_REG 1, $C0
t2:
        ld b, 8
        call frames
s3:     VDP_REG 0, $02          ; R#4 = $02
        VDP_REG 3, $FF
        VDP_REG 4, $02
        VDP_REG 1, $C0
t3:
        ld b, 8
        call frames
s4:     VDP_REG 0, $02          ; R#3 = $9F: one set of colours
        VDP_REG 3, $9F
        VDP_REG 4, $03
        VDP_REG 1, $C0
t4:
        ld b, 8
        call frames
s5:     VDP_REG 0, $02          ; R#3 = $BF
        VDP_REG 3, $BF
        VDP_REG 4, $03
        VDP_REG 1, $C0
t5:
        ld b, 8
        call frames
s6:     VDP_REG 0, $02          ; R#3 = $DF
        VDP_REG 3, $DF
        VDP_REG 4, $03
        VDP_REG 1, $C0
t6:
        ld b, 8
        call frames
s7:     VDP_REG 0, $02          ; M1 and M3
        VDP_REG 3, $FF
        VDP_REG 4, $03
        VDP_REG 1, $D0
t7:
        ld b, 8
        call frames
s8:     VDP_REG 0, $02          ; M2 and M3
        VDP_REG 3, $FF
        VDP_REG 4, $03
        VDP_REG 1, $C8
t8:
done:   jr done

; digit: A = a character, DE = a third's shapes: its shape, 256 times over
digit:  ld l, a
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        push de
        ld de, (CGTABL)
        add hl, de              ; HL: the BIOS's shape of A
        pop de
        ld a, e
        out (VDP_CTRL), a
        ld a, d
        or $40
        out (VDP_CTRL), a
        ld e, 0                 ; 256 times
.next:  push hl
        ld b, 8
        ld c, VDP_DATA
        otir
        pop hl
        dec e
        jr nz, .next
        ret

; frames: wait for B frame flags, the interrupts off (chapter 19's status)
frames: in a, (VDP_CTRL)        ; bit 7, F: a frame has ended
        rla
        jr nc, frames
        djnz frames
        ret
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
